            s = 0;
        } else if (max == r) {
            h = (g - b) / delta;
        } else if (max == g) {
            h = 2 + (b - r) / delta;
        } else {
            h = 4 + (r - g) / delta;
        }

        h *= 60;
        if (h < 0) {
            h += 360;
        }

        if (max == min) {
            s = 0;
        } else {
            s = delta / (1 - Math.abs(2 * l - 1));
        }

        return new int[]{(int) h, (int) s * 100, (int) l * 100};
    }
}
