public class ColorConverter {
    public static String rgbToHex(int red, int green, int blue) {
        // Ensure the values are in the range 0-255
        red = Math.max(0, Math.min(255, red));
        green = Math.max(0, Math.min(255, green));
        blue = Math.max(0, Math.min(255, blue));

        // Convert the RGB values to hexadecimal
        String hexRed = Integer.toHexString(red).toUpperCase();
        String hexGreen = Integer.toHexString(green).toUpperCase();
        String hexBlue = Integer.toHexString(blue).toUpperCase();

        // Pad the hexadecimal values with zeros if necessary
        while (hexRed.length() < 2) {
            hexRed = "0" + hexRed;
        }
        while (hexGreen.length() < 2) {
            hexGreen = "0" + hexGreen;
        }
        while (hexBlue.length() < 2) {
            hexBlue = "0" + hexBlue;
        }

        // Combine the hexadecimal values into a single string
        return "#" + hexRed + hexGreen + hexBlue;
    }

    public static void main(String[] args) {
        int red = 255;
        int green = 0;
        int blue = 0;
        System.out.println(rgbToHex(red, green, blue));  // Output: #ff0000
    }
}
